def _fbp_effect_state_key(effect_id, suffix):
    return fbp_effect_storage_key(
        "fbp_effect_", fbp_normalize_effect_id(effect_id), f"_{suffix}"
    )


def _fbp_effect_ref(effect_id, instance_id=""):
    """Return the concrete persistent token used by instance-aware subsystems."""
    effect_id = fbp_normalize_effect_id(effect_id)
    instance_id = str(instance_id or "")
    if not effect_id:
        return ""
    return effect_instance_token(effect_id, instance_id) if instance_id else effect_id


def _fbp_effect_ref_parts(value):
    """Split one concrete effect token; SINGLE effects use an empty instance id."""
    effect_id, instance_id = split_effect_instance_token(str(value or ""))
    return fbp_normalize_effect_id(effect_id), str(instance_id or "")


def _fbp_effect_ref_effect_id(value):
    return _fbp_effect_ref_parts(value)[0]


def _fbp_effect_ref_instance_id(value):
    return _fbp_effect_ref_parts(value)[1]


def _fbp_effect_ref_is_active(rig, value):
    effect_id, instance_id = _fbp_effect_ref_parts(value)
    if not effect_id or not fbp_effect_is_active(rig, effect_id):
        return False
    if not instance_id:
        return True
    definition = fbp_effect_definition(effect_id)
    if definition.get("kind") == "SHADER":
        return bool(_fbp_find_shader_effect_nodes_for_rig(
            rig, effect_id, instance_id=instance_id
        ))
    if definition.get("kind") == "GEOMETRY":
        return bool(fbp_find_effect_modifier(rig, effect_id, instance_id=instance_id))
    return False


def _fbp_normalize_effect_refs(values):
    """Return unique concrete stack references while preserving input order."""
    result = []
    seen = set()
    for value in tuple(values or ()):
        effect_id, instance_id = _fbp_effect_ref_parts(value)
        if not effect_id:
            continue
        if not _fbp_effect_uses_multi_instances(effect_id):
            instance_id = ""
        token = _fbp_effect_ref(effect_id, instance_id)
        if token and token not in seen:
            result.append(token)
            seen.add(token)
    return result


def _fbp_effect_mask_target_key(mask_effect_id):
    return _fbp_effect_state_key(mask_effect_id, "mask_target")


def _fbp_effect_is_local_mask(mask_effect_id):
    definition = fbp_effect_definition(mask_effect_id)
    return bool(
        definition.get("kind") == "SHADER"
        and str(definition.get("stage", "") or "") == "MASK"
        and str(definition.get("mask_output_socket", "") or "")
        and (
            not bool(definition.get("layer_feature", False))
            or bool(definition.get("local_mask_capable", False))
        )
    )


FBP_MASK_STACK_SCHEMA_VERSION = 1
FBP_MASK_STACK_KEY = "fbp_mask_stack_v1"
FBP_MASK_STACK_OPERATIONS = (
    ("ADD", "Add", "Union this mask with the accumulated matte"),
    (
        "SUBTRACT",
        "Subtract",
        "Remove this mask from the accumulated matte",
    ),
    (
        "INTERSECT",
        "Intersect",
        "Keep only the overlap with the accumulated matte",
    ),
    (
        "DIFFERENCE",
        "Difference",
        "Keep areas covered by exactly one of the two mattes",
    ),
)
_FBP_MASK_STACK_OPERATION_IDS = frozenset(
    item[0] for item in FBP_MASK_STACK_OPERATIONS
)


def _fbp_mask_stack_payload(rig):
    """Decode persistent mask operations; unspecified operations use Intersect."""
    if rig is None:
        return {
            "schema": FBP_MASK_STACK_SCHEMA_VERSION,
            "operations": {},
        }, ""
    try:
        raw = str(rig.get(FBP_MASK_STACK_KEY, "") or "")
    except FBP_DATA_ERRORS:
        raw = ""
    if not raw:
        return {
            "schema": FBP_MASK_STACK_SCHEMA_VERSION,
            "operations": {},
        }, ""
    try:
        payload = json.loads(raw)
    except (json.JSONDecodeError, TypeError, ValueError):
        return None, "Mask Stack metadata is not valid JSON"
    if not isinstance(payload, dict):
        return None, "Mask Stack metadata root must be an object"
    try:
        schema = int(payload.get("schema", 0) or 0)
    except (TypeError, ValueError):
        schema = 0
    if schema != FBP_MASK_STACK_SCHEMA_VERSION:
        return None, f"Mask Stack schema {schema} is not supported"
    operations = payload.get("operations", {})
    if not isinstance(operations, dict):
        return None, "Mask Stack operations must be an object"
    return {
        "schema": FBP_MASK_STACK_SCHEMA_VERSION,
        "operations": {
            fbp_normalize_effect_id(effect_id): str(operation or "").upper()
            for effect_id, operation in operations.items()
            if fbp_normalize_effect_id(effect_id)
        },
    }, ""


def _fbp_store_mask_stack_payload(rig, payload):
    if rig is None:
        return False
    operations = {
        fbp_normalize_effect_id(effect_id): str(operation or "").upper()
        for effect_id, operation in dict(
            (payload or {}).get("operations", {}) or {}
        ).items()
        if (
            fbp_normalize_effect_id(effect_id)
            and str(operation or "").upper()
            in _FBP_MASK_STACK_OPERATION_IDS
            and str(operation or "").upper() != "INTERSECT"
        )
    }
    canonical = {
        "schema": FBP_MASK_STACK_SCHEMA_VERSION,
        "operations": dict(sorted(operations.items())),
    }
    try:
        if not operations:
            if FBP_MASK_STACK_KEY in rig:
                del rig[FBP_MASK_STACK_KEY]
                return True
            return False
        encoded = json.dumps(
            canonical,
            ensure_ascii=True,
            sort_keys=True,
            separators=(",", ":"),
        )
        if str(rig.get(FBP_MASK_STACK_KEY, "") or "") == encoded:
            return False
        rig[FBP_MASK_STACK_KEY] = encoded
        return True
    except FBP_DATA_ERRORS:
        return False


def fbp_mask_stack_operation(rig, mask_effect_id):
    mask_effect_id = fbp_normalize_effect_id(mask_effect_id)
    payload, _error = _fbp_mask_stack_payload(rig)
    operation = (
        str(
            dict((payload or {}).get("operations", {}) or {}).get(
                mask_effect_id,
                "INTERSECT",
            )
            or "INTERSECT"
        ).upper()
    )
    return (
        operation
        if operation in _FBP_MASK_STACK_OPERATION_IDS
        else "INTERSECT"
    )


def fbp_mask_stack_snapshot(rig):
    """Return versioned operation metadata for a complete stack snapshot."""
    payload, _error = _fbp_mask_stack_payload(rig)
    operations = {}
    active = set(fbp_effect_ids_for_rig(rig)) if rig is not None else set()
    for effect_id, operation in dict(
        (payload or {}).get("operations", {}) or {}
    ).items():
        definition = fbp_effect_definition(effect_id)
        if (
            effect_id in active
            and str(definition.get("stage", "") or "") == "MASK"
            and operation in _FBP_MASK_STACK_OPERATION_IDS
        ):
            operations[effect_id] = operation
    return {
        "schema": FBP_MASK_STACK_SCHEMA_VERSION,
        "operations": dict(sorted(operations.items())),
    }


def fbp_set_mask_stack_operation(
    rig,
    mask_effect_id,
    operation,
    *,
    rebuild=True,
):
    """Set one ordered mask boolean operation and rebuild owned materials."""
    mask_effect_id = fbp_normalize_effect_id(mask_effect_id)
    operation = str(operation or "INTERSECT").upper()
    definition = fbp_effect_definition(mask_effect_id)
    if (
        rig is None
        or operation not in _FBP_MASK_STACK_OPERATION_IDS
        or str(definition.get("stage", "") or "") != "MASK"
        or not fbp_effect_is_active(rig, mask_effect_id)
    ):
        return False
    payload, error = _fbp_mask_stack_payload(rig)
    if payload is None:
        payload = {
            "schema": FBP_MASK_STACK_SCHEMA_VERSION,
            "operations": {},
        }
    operations = dict(payload.get("operations", {}) or {})
    previous = str(
        operations.get(mask_effect_id, "INTERSECT") or "INTERSECT"
    ).upper()
    if operation == "INTERSECT":
        operations.pop(mask_effect_id, None)
    else:
        operations[mask_effect_id] = operation
    payload["operations"] = operations
    changed = _fbp_store_mask_stack_payload(rig, payload)
    if not changed and previous == operation and not error:
        return False
    if rebuild:
        for material in _fbp_plane_materials(rig):
            _fbp_rebuild_shader_stage(material, "MASK")
    return True


def fbp_apply_mask_stack_snapshot(rig, payload, *, rebuild=True):
    if rig is None or not isinstance(payload, dict):
        return False
    try:
        schema = int(payload.get("schema", 0) or 0)
    except (TypeError, ValueError):
        schema = 0
    if schema != FBP_MASK_STACK_SCHEMA_VERSION:
        return False
    active = set(fbp_effect_ids_for_rig(rig))
    operations = {}
    for effect_id, operation in dict(
        payload.get("operations", {}) or {}
    ).items():
        effect_id = fbp_normalize_effect_id(effect_id)
        operation = str(operation or "").upper()
        definition = fbp_effect_definition(effect_id)
        if (
            effect_id in active
            and str(definition.get("stage", "") or "") == "MASK"
            and operation in _FBP_MASK_STACK_OPERATION_IDS
        ):
            operations[effect_id] = operation
    _fbp_store_mask_stack_payload(
        rig,
        {
            "schema": FBP_MASK_STACK_SCHEMA_VERSION,
            "operations": operations,
        },
    )
    if rebuild:
        for material in _fbp_plane_materials(rig):
            _fbp_rebuild_shader_stage(material, "MASK")
    return True


def audit_mask_stack_rig(rig, *, repair=False):
    issues = []
    warnings = []
    repaired = 0
    payload, error = _fbp_mask_stack_payload(rig)
    if error:
        issues.append(error)
        if repair:
            try:
                if FBP_MASK_STACK_KEY in rig:
                    del rig[FBP_MASK_STACK_KEY]
                    repaired += 1
            except FBP_DATA_ERRORS:
                pass
        return {
            "issues": tuple(issues),
            "warnings": tuple(warnings),
            "repaired": repaired,
        }
    active = set(fbp_effect_ids_for_rig(rig)) if rig is not None else set()
    cleaned = {}
    for effect_id, operation in dict(
        (payload or {}).get("operations", {}) or {}
    ).items():
        definition = fbp_effect_definition(effect_id)
        if str(definition.get("stage", "") or "") != "MASK":
            warnings.append(f"{effect_id}: Mask Stack record is not a mask")
            continue
        if effect_id not in active:
            warnings.append(f"{effect_id}: Mask Stack record is stale")
            continue
        if operation not in _FBP_MASK_STACK_OPERATION_IDS:
            issues.append(
                f"{effect_id}: unsupported Mask Stack operation {operation}"
            )
            continue
        cleaned[effect_id] = operation
    if repair:
        normalized = {
            "schema": FBP_MASK_STACK_SCHEMA_VERSION,
            "operations": cleaned,
        }
        before = str(getattr(rig, "get", lambda *_args: "")(
            FBP_MASK_STACK_KEY,
            "",
        ) or "")
        _fbp_store_mask_stack_payload(rig, normalized)
        after = str(getattr(rig, "get", lambda *_args: "")(
            FBP_MASK_STACK_KEY,
            "",
        ) or "")
        if before != after:
            repaired += 1
    return {
        "issues": tuple(dict.fromkeys(issues)),
        "warnings": tuple(dict.fromkeys(warnings)),
        "repaired": repaired,
    }


def _fbp_effect_can_receive_mask(effect_id):
    definition = fbp_effect_definition(effect_id)
    return bool(
        definition.get("kind") == "SHADER"
        and str(definition.get("stage", "") or "") in {"UV", "COLOR"}
        and str(definition.get("input_socket", "") or "")
        and str(definition.get("output_socket", "") or "")
    )


def fbp_effect_mask_target(rig, mask_effect_id):
    """Return the receiving registry ID for the current mask target."""
    target = fbp_effect_mask_target_ref(rig, mask_effect_id)
    return _fbp_effect_ref_effect_id(target) if target != "LAYER" else "LAYER"


def fbp_effect_mask_raw_target_ref(rig, mask_effect_id):
    """Return the stored concrete receiver token without validity fallback."""
    mask_effect_id = fbp_normalize_effect_id(mask_effect_id)
    if not rig or not _fbp_effect_is_local_mask(mask_effect_id):
        return "LAYER"
    try:
        raw = str(rig.get(_fbp_effect_mask_target_key(mask_effect_id), "LAYER") or "LAYER")
    except FBP_DATA_ERRORS:
        return "LAYER"
    if raw == "LAYER":
        return "LAYER"
    effect_id, instance_id = _fbp_effect_ref_parts(raw)
    return _fbp_effect_ref(effect_id, instance_id) if effect_id else "LAYER"


def fbp_effect_mask_target_ref(rig, mask_effect_id):
    """Return the valid concrete receiver token for one local mask."""
    target = fbp_effect_mask_raw_target_ref(rig, mask_effect_id)
    if target == "LAYER":
        return "LAYER"
    effect_id = _fbp_effect_ref_effect_id(target)
    if not _fbp_effect_can_receive_mask(effect_id) or not _fbp_effect_ref_is_active(rig, target):
        return "LAYER"
    return target



def fbp_effect_mask_raw_target(rig, mask_effect_id):
    """Return the stored receiver registry ID for diagnostics compatibility."""
    target = fbp_effect_mask_raw_target_ref(rig, mask_effect_id)
    return _fbp_effect_ref_effect_id(target) if target != "LAYER" else "LAYER"



def fbp_local_effect_mask_contract_report(rig, *, repair=False):
    """Validate per-effect mask assignments and generated receiver wiring.

    Repair mode is deliberately non-destructive: invalid targets are returned
    to the whole-layer route and generated UV/Color receiver helpers are rebuilt
    from the active effect stack. User mask values, helper geometry and source
    media are never deleted.
    """
    stats = {
        "local_mask_effects": 0,
        "local_mask_targets": 0,
        "local_mask_invalid_targets": 0,
        "local_mask_materials": 0,
        "local_mask_stale_wiring": 0,
        "local_mask_stale_helpers": 0,
        "local_mask_repairs": 0,
    }
    issues = []
    warnings = []
    if not rig:
        return {"stats": stats, "issues": (), "warnings": (), "repaired": 0}

    rig_name = str(getattr(rig, "name", "<rig>") or "<rig>")
    active_ids = tuple(fbp_effect_ids_for_rig(rig))
    local_masks = tuple(
        effect_id for effect_id in active_ids
        if _fbp_effect_is_local_mask(effect_id)
    )
    stats["local_mask_effects"] = len(local_masks)
    valid_targets = []

    for mask_id in local_masks:
        raw_target = fbp_effect_mask_raw_target_ref(rig, mask_id)
        if raw_target == "LAYER":
            continue
        stats["local_mask_targets"] += 1
        target_effect_id, _target_instance_id = _fbp_effect_ref_parts(raw_target)
        reason = ""
        if target_effect_id == mask_id:
            reason = "targets itself"
        elif not _fbp_effect_ref_is_active(rig, raw_target):
            reason = f"targets inactive or missing effect instance {raw_target}"
        elif not _fbp_effect_can_receive_mask(target_effect_id):
            reason = f"targets incompatible effect {target_effect_id}"
        if reason:
            stats["local_mask_invalid_targets"] += 1
            issues.append(f"{rig_name}: {mask_id} {reason}")
            if repair and fbp_set_effect_mask_target(rig, mask_id, "LAYER"):
                stats["local_mask_repairs"] += 1
            continue
        valid_targets.append(raw_target)

    materials = tuple(_fbp_plane_materials(rig))
    stats["local_mask_materials"] = len(materials)
    has_local_routes = bool(valid_targets)
    for material in materials:
        material_name = str(getattr(material, "name", "<material>") or "<material>")
        try:
            version = int(
                material.get("fbp_local_effect_mask_wiring_version", 0) or 0
            )
        except FBP_DATA_ERRORS:
            version = 0
        try:
            helper_nodes = tuple(_fbp_local_mask_helper_nodes(material))
            # Global Mask Stack helpers also use the common helper marker, but
            # they are not local receiver wiring. Only UV/Color receiver mixers
            # carrying an explicit concrete target belong to this contract.
            routing_helpers = tuple(
                node for node in helper_nodes
                if (
                    not bool(node.get("fbp_local_effect_mask_preview", False))
                    and str(node.get("fbp_local_effect_mask_kind", "") or "").upper()
                    in {"UV", "COLOR"}
                    and str(node.get("fbp_local_effect_mask_target", "") or "").strip()
                )
            )
        except FBP_DATA_ERRORS:
            helper_nodes = ()
            routing_helpers = ()
        stale_helpers = []
        for node in routing_helpers:
            try:
                raw_target = str(
                    node.get("fbp_local_effect_mask_target", "") or ""
                )
                target_effect_id, target_instance_id = _fbp_effect_ref_parts(raw_target)
                target = _fbp_effect_ref(target_effect_id, target_instance_id)
            except FBP_DATA_ERRORS:
                target = ""
            if target and not _fbp_effect_ref_is_active(rig, target):
                stale_helpers.append(target)
        if stale_helpers:
            stats["local_mask_stale_helpers"] += len(stale_helpers)
            warnings.append(
                f"{rig_name}/{material_name}: stale local-mask helper target(s): "
                + ", ".join(sorted(set(stale_helpers)))
            )

        wiring_stale = bool(
            (has_local_routes and version < FBP_LOCAL_EFFECT_MASK_WIRING_VERSION)
            or stale_helpers
            or (not has_local_routes and routing_helpers)
        )
        if wiring_stale:
            stats["local_mask_stale_wiring"] += 1
            issues.append(
                f"{rig_name}/{material_name}: local-mask receiver wiring is stale"
            )
            if repair:
                try:
                    if _fbp_rebuild_local_mask_receivers(material):
                        stats["local_mask_repairs"] += 1
                except FBP_DATA_ERRORS:
                    pass

    _fbp_invalidate_mask_target_cache(rig)
    return {
        "stats": stats,
        "issues": tuple(issues),
        "warnings": tuple(warnings),
        "repaired": int(stats["local_mask_repairs"]),
    }


def _fbp_mask_target_cache_key(rig):
    """Return a cache identity that cannot alias a newly created Blender ID."""
    key = fbp_obj_runtime_key(rig) if rig is not None else None
    return key if key is not None else id(rig)


def _fbp_invalidate_mask_target_cache(rig=None):
    """Invalidate the lightweight local-mask target lookup cache."""
    if rig is None:
        _FBP_MASK_TARGET_CACHE.clear()
        return
    _FBP_MASK_TARGET_CACHE.pop(_fbp_mask_target_cache_key(rig), None)


def _fbp_mask_target_map(rig):
    """Return concrete target token -> local mask IDs with bounded validation."""
    if not rig:
        return {}
    key = _fbp_mask_target_cache_key(rig)
    now = time.monotonic()
    cached = _FBP_MASK_TARGET_CACHE.get(key)
    if isinstance(cached, tuple) and len(cached) == 3:
        cached_time, cached_signature, cached_map = cached
        if now - float(cached_time) < _FBP_MASK_TARGET_CACHE_SECONDS:
            return cached_map
    else:
        cached_signature, cached_map = None, None
    effect_ids = tuple(fbp_effect_ids_for_rig(rig))
    local_mask_ids = tuple(mask_id for mask_id in effect_ids if _fbp_effect_is_local_mask(mask_id))
    signature_parts = tuple((mask_id, fbp_effect_mask_raw_target_ref(rig, mask_id)) for mask_id in local_mask_ids)
    signature = (effect_ids, signature_parts)
    if cached_map is not None and signature == cached_signature:
        _FBP_MASK_TARGET_CACHE[key] = (now, signature, cached_map)
        return cached_map
    result = {}
    for mask_id, _raw_target in signature_parts:
        target = fbp_effect_mask_target_ref(rig, mask_id)
        if target != "LAYER":
            result.setdefault(target, []).append(mask_id)
    frozen = {target: tuple(mask_ids) for target, mask_ids in result.items()}
    if len(_FBP_MASK_TARGET_CACHE) >= 1024 and key not in _FBP_MASK_TARGET_CACHE:
        _FBP_MASK_TARGET_CACHE.clear()
    _FBP_MASK_TARGET_CACHE[key] = (now, signature, frozen)
    return frozen



def fbp_masks_targeting_effect(rig, effect_id, instance_id=""):
    effect_id = fbp_normalize_effect_id(effect_id)
    if not rig or not effect_id:
        return ()
    target = _fbp_effect_ref(
        effect_id, instance_id if _fbp_effect_uses_multi_instances(effect_id) else ""
    )
    return _fbp_mask_target_map(rig).get(target, ())



def _fbp_effect_mask_target_stage(effect_ref):
    effect_id = _fbp_effect_ref_effect_id(effect_ref)
    if not effect_id or effect_ref == "LAYER":
        return "LAYER"
    if not _fbp_effect_can_receive_mask(effect_id):
        return "LAYER"
    return str(fbp_effect_definition(effect_id).get("stage", "") or "").upper()



def _fbp_rebuild_mask_target_routing(material, previous_target, target_effect_id):
    """Rebuild only the receiver stages affected by one mask reassignment.

    Moving a mask between the whole layer and a UV effect does not require the
    complete Color stack to be reconstructed. Color targets still rebuild the
    Color stage because that stage also restores the alpha chain. UV-only
    changes rebuild UV and relink alpha directly.
    """
    if not material or not material.node_tree:
        return False
    previous_stage = _fbp_effect_mask_target_stage(previous_target)
    target_stage = _fbp_effect_mask_target_stage(target_effect_id)
    stages = {stage for stage in (previous_stage, target_stage) if stage in {"UV", "COLOR"}}
    # A UV-only reassignment normally avoids the Color stack. Diagnostic Matte
    # preview is the exception because its temporary grayscale node lives in
    # that stack. Rebuild Color only while a preview exists or must be removed.
    rig = None
    try:
        owner_name = str(material.get("fbp_effect_rig_owner", "") or "")
        rig = bpy.data.objects.get(owner_name) if owner_name else None
    except FBP_DATA_ERRORS:
        rig = None
    preview_helpers = any(
        bool(node.get("fbp_local_effect_mask_preview", False))
        for node in _fbp_local_mask_helper_nodes(material, kind="COLOR")
    )
    preview_socket = None
    if rig is not None:
        preview_socket, _preview_id = _fbp_local_mask_preview_socket(
            rig, _fbp_stage_effect_nodes(material, "MASK")
        )
    if preview_helpers or preview_socket is not None:
        stages.add("COLOR")

    changed = False
    if "UV" in stages:
        changed = _fbp_rebuild_shader_stage(material, "UV") or changed
    if "COLOR" in stages:
        changed = _fbp_rebuild_shader_stage(material, "COLOR") or changed
    else:
        image_node = _fbp_shader_image_node(material)
        layer_alpha = _fbp_material_layer_alpha_source(material, image_node)
        changed = _fbp_relink_effect_alpha(
            material,
            _fbp_color_stage_evaluation_nodes(material),
            layer_alpha,
        ) or changed
    try:
        if int(material.get("fbp_local_effect_mask_wiring_version", 0) or 0) != FBP_LOCAL_EFFECT_MASK_WIRING_VERSION:
            material["fbp_local_effect_mask_wiring_version"] = FBP_LOCAL_EFFECT_MASK_WIRING_VERSION
            changed = True
    except FBP_DATA_ERRORS:
        pass
    return changed


def _fbp_rebuild_mask_target_batch(material, target_effect_ids):
    """Rebuild local-mask receiver stages once for a group of targets."""
    targets = []
    seen = set()
    for value in tuple(target_effect_ids or ()):
        effect_id, instance_id = _fbp_effect_ref_parts(value)
        if not effect_id:
            effect_id = fbp_normalize_effect_id(value)
        if not _fbp_effect_uses_multi_instances(effect_id):
            instance_id = ""
        target = _fbp_effect_ref(effect_id, instance_id)
        if not target or target in seen:
            continue
        seen.add(target)
        targets.append(target)
    if not targets:
        return False
    uv_target = next(
        (value for value in targets if _fbp_effect_mask_target_stage(value) == "UV"),
        None,
    )
    color_target = next(
        (value for value in targets if _fbp_effect_mask_target_stage(value) == "COLOR"),
        None,
    )
    if uv_target and color_target:
        return _fbp_rebuild_mask_target_routing(material, uv_target, color_target)
    target = uv_target or color_target or "LAYER"
    return _fbp_rebuild_mask_target_routing(material, target, target)


def fbp_set_effect_mask_target(
    rig, mask_effect_id, target_effect_id, target_instance_id=""
):
    mask_effect_id = fbp_normalize_effect_id(mask_effect_id)
    if (
        not rig or not _fbp_effect_is_local_mask(mask_effect_id)
        or not fbp_effect_is_active(rig, mask_effect_id)
    ):
        return False
    raw_effect, raw_instance = _fbp_effect_ref_parts(target_effect_id)
    target_effect_id = raw_effect or fbp_normalize_effect_id(target_effect_id)
    target_instance_id = str(target_instance_id or raw_instance or "")
    if not _fbp_effect_uses_multi_instances(target_effect_id):
        target_instance_id = ""
    target_ref = _fbp_effect_ref(target_effect_id, target_instance_id)
    if (
        not target_effect_id or target_effect_id == mask_effect_id
        or not _fbp_effect_can_receive_mask(target_effect_id)
        or not _fbp_effect_ref_is_active(rig, target_ref)
    ):
        target_ref = "LAYER"
    key = _fbp_effect_mask_target_key(mask_effect_id)
    previous_effective = fbp_effect_mask_target_ref(rig, mask_effect_id)
    previous_raw = fbp_effect_mask_raw_target_ref(rig, mask_effect_id)
    if previous_raw == target_ref and previous_effective == target_ref:
        return False
    try:
        if target_ref == "LAYER":
            if key in rig:
                del rig[key]
        else:
            rig[key] = target_ref
    except FBP_DATA_ERRORS:
        return False
    _fbp_invalidate_mask_target_cache(rig)
    changed = False
    for material in _fbp_plane_materials(rig):
        changed = _fbp_rebuild_mask_target_routing(material, previous_effective, target_ref) or changed
    return changed or previous_raw != target_ref



def _fbp_effect_input_source_key(effect_id, instance_id=""):
    effect_id = fbp_normalize_effect_id(effect_id)
    instance_id = str(instance_id or "")
    owner_ref = (
        _fbp_effect_ref(effect_id, instance_id)
        if instance_id and _fbp_effect_uses_multi_instances(effect_id)
        else effect_id
    )
    return _fbp_effect_state_key(owner_ref, "input_source")


def fbp_effect_input_source(rig, effect_id, instance_id=""):
    definition = fbp_effect_definition(effect_id)
    if not rig or not definition.get("supports_input_source"):
        return "PREVIOUS"
    default_source = str(definition.get("default_input_source", "PREVIOUS") or "PREVIOUS").upper()
    if default_source not in {"PREVIOUS", "ORIGINAL", "FINAL"}:
        default_source = "PREVIOUS"
    instance_id = str(instance_id or "")
    key = _fbp_effect_input_source_key(effect_id, instance_id)
    try:
        value = str(rig.get(key, default_source) or default_source).upper()
    except FBP_DATA_ERRORS:
        value = default_source
    return value if value in {"PREVIOUS", "ORIGINAL", "FINAL"} else default_source


def fbp_set_effect_input_source(rig, effect_id, source, instance_id=""):
    definition = fbp_effect_definition(effect_id)
    if not rig or not definition.get("supports_input_source"):
        return False
    source = str(source or "PREVIOUS").upper()
    default_source = str(definition.get("default_input_source", "PREVIOUS") or "PREVIOUS").upper()
    if default_source not in {"PREVIOUS", "ORIGINAL", "FINAL"}:
        default_source = "PREVIOUS"
    if source not in {"PREVIOUS", "ORIGINAL", "FINAL"}:
        source = default_source
    instance_id = str(instance_id or "")
    key = _fbp_effect_input_source_key(effect_id, instance_id)
    try:
        if fbp_effect_input_source(rig, effect_id, instance_id) == source and key in rig:
            return False
        rig[key] = source
    except FBP_DATA_ERRORS:
        return False
    if definition.get("kind") == "SHADER":
        for material in _fbp_plane_materials(rig):
            _fbp_rebuild_shader_stage(material, str(definition.get("stage", "COLOR")))
    return True


def _fbp_clear_effect_input_source(rig, effect_id, instance_id=""):
    key = _fbp_effect_input_source_key(effect_id, instance_id)
    try:
        if key in rig:
            del rig[key]
            return True
    except FBP_DATA_ERRORS:
        pass
    return False


def fbp_effect_debug_mode(rig, effect_id):
    definition = fbp_effect_definition(effect_id)
    modes = tuple(item[0] for item in definition.get("debug_modes", ()))
    if not modes:
        return "FINAL"
    try:
        value = str(rig.get(_fbp_effect_state_key(effect_id, "debug"), "FINAL") or "FINAL").upper()
    except FBP_DATA_ERRORS:
        value = "FINAL"
    return value if value in modes else modes[0]


def fbp_set_effect_debug_mode(rig, effect_id, mode):
    definition = fbp_effect_definition(effect_id)
    modes = tuple(item[0] for item in definition.get("debug_modes", ()))
    if not rig or not modes:
        return False
    effect_id = fbp_normalize_effect_id(effect_id)
    mode = str(mode or modes[0]).upper()
    if mode not in modes:
        mode = modes[0]

    is_local_preview = bool(
        _fbp_effect_is_local_mask(effect_id)
        and fbp_effect_mask_target(rig, effect_id) != "LAYER"
    )
    reset_preview_ids = []
    if is_local_preview and mode != "FINAL":
        # Only one local mask diagnostic can replace the layer color at a time.
        # Reset older previews silently, then rebuild the COLOR stage once.
        for other_id in fbp_effect_ids_for_rig(rig):
            if other_id == effect_id or not _fbp_effect_is_local_mask(other_id):
                continue
            if fbp_effect_mask_target(rig, other_id) == "LAYER":
                continue
            if fbp_effect_debug_mode(rig, other_id) == "FINAL":
                continue
            try:
                rig[_fbp_effect_state_key(other_id, "debug")] = "FINAL"
                reset_preview_ids.append(other_id)
            except FBP_DATA_ERRORS:
                continue

    key = _fbp_effect_state_key(effect_id, "debug")
    try:
        current = str(rig.get(key, modes[0]) or modes[0]).upper()
        if current != mode:
            rig[key] = mode
            selected_changed = True
        else:
            selected_changed = False
    except FBP_DATA_ERRORS:
        return False
    if not selected_changed and not reset_preview_ids:
        return False

    if definition.get("kind") == "SHADER":
        changed = False
        for other_id in reset_preview_ids:
            changed = fbp_update_shader_effect(rig, other_id) or changed
        if selected_changed:
            changed = fbp_update_shader_effect(rig, effect_id) or changed
        if is_local_preview or reset_preview_ids:
            for material in _fbp_plane_materials(rig):
                changed = _fbp_rebuild_shader_stage(material, "COLOR") or changed
        return changed or True
    return fbp_update_geometry_effect(rig, effect_id) or True


def _fbp_debug_mode_value(definition, mode):
    modes = tuple(item[0] for item in definition.get("debug_modes", ()))
    try:
        return float(modes.index(str(mode or "FINAL").upper()))
    except ValueError:
        return 0.0


def _fbp_stored_effect_render_visibility(rig, effect_id, default=True):
    if not rig:
        return bool(default)
    try:
        return bool(rig.get(_fbp_effect_render_visibility_key(effect_id), default))
    except FBP_DATA_IO_ERRORS:
        return bool(default)


