def _fbp_stabilize_existing_lattice_helpers():
    """Upgrade cages and heal active contracts once outside UI/depsgraph draw."""
    try:
        objects = tuple(getattr(bpy.data, "objects", ()) or ())
    except FBP_DATA_ERRORS:
        return None
    for helper in objects:
        try:
            if (
                str(getattr(helper, "type", "") or "") == "LATTICE"
                and str(helper.get(_FBP_LATTICE_EFFECT_KEY, "") or "") == FBP_EFFECT_LATTICE
            ):
                _fbp_stabilize_lattice_helper(helper)
        except FBP_DATA_ERRORS:
            continue
    fbp_repair_existing_lattice_contracts()
    return None


def _fbp_remove_object_context_menu_entry():
    menu_type = getattr(bpy.types, "VIEW3D_MT_object_context_menu", None)
    if menu_type is None:
        return
    callbacks = (
        _FBP_PREVIOUS_OBJECT_CONTEXT_CALLBACK,
        _fbp_draw_object_context_effects,
    )
    seen = set()
    for callback in callbacks:
        if not callable(callback) or id(callback) in seen:
            continue
        seen.add(id(callback))
        try:
            menu_type.remove(callback)
        except (AttributeError, RuntimeError, ValueError):
            pass


def register():
    register_clipping_matrix_driver_namespace()
    fbp_clear_effect_runtime_caches()
    for issue in FBP_EFFECT_REGISTRY_ISSUES:
        fbp_warn(f"Effect registry validation: {issue}")
    for issue in FBP_EFFECT_SETTINGS_UI_ISSUES:
        fbp_warn(f"Effect settings UI validation: {issue}")
    is_background = bool(getattr(bpy.app, "background", False))
    classes_registered = False
    try:
        if not is_background:
            register_classes(classes)
            classes_registered = True
        # Effect evolution is render data and remains active in the child. Menus,
        # playback UI callbacks and delayed cage maintenance are interactive-only.
        _fbp_remove_object_context_menu_entry()
        _fbp_remove_evolve_handlers()
        if not append_handler_once(
            bpy.app.handlers.frame_change_post,
            fbp_effect_evolve_frame_change,
            module_suffix="geometry_nodes",
        ):
            raise RuntimeError("Could not register the effect evolution handler")
        if not is_background:
            if not append_handler_once(
                bpy.app.handlers.animation_playback_pre,
                fbp_effect_playback_pre,
                module_suffix="geometry_nodes",
            ):
                raise RuntimeError("Could not register the effect playback-start handler")
            if not append_handler_once(
                bpy.app.handlers.animation_playback_post,
                fbp_effect_playback_post,
                module_suffix="geometry_nodes",
            ):
                raise RuntimeError("Could not register the effect playback-stop handler")
            try:
                from .safe_tasks import schedule_once
                schedule_once(
                    "lattice.stabilize_native_cages",
                    _fbp_stabilize_existing_lattice_helpers,
                    first_interval=0.05,
                )
            except (ImportError, AttributeError, ReferenceError, RuntimeError, TypeError, ValueError):
                pass
    except Exception:
        _fbp_remove_evolve_handlers()
        _fbp_remove_object_context_menu_entry()
        if classes_registered:
            unregister_classes(classes)
        unregister_clipping_matrix_driver_namespace()
        raise


def unregister():
    global _FBP_EFFECT_PLAYBACK_ACTIVE, _FBP_SELECTED_RIGS_FN
    unregister_clipping_matrix_driver_namespace()
    _FBP_EFFECT_PLAYBACK_ACTIVE = False
    _FBP_SELECTED_RIGS_FN = None
    fbp_clear_effect_runtime_caches()
    _fbp_remove_object_context_menu_entry()
    _fbp_remove_evolve_handlers()
    unregister_classes(classes)
